<script setup>
import { inject } from 'vue'
import { ArrowRight, Compass, Plus, X } from 'lucide-vue-next'
import { homeContextKey } from '../../composables/homeContext'

const home = inject(homeContextKey)
</script>

<template>
  <section class="page-view">
    <div class="view-heading"><div><p class="view-kicker">KẾ HOẠCH CỦA BẠN</p><h1>Lộ trình học</h1><p>Theo dõi mục tiêu và lịch học được xây dựng cho bạn.</p></div><button class="primary-button" @click="home.showPlanForm = !home.showPlanForm"><Plus :size="17" /> Tạo lộ trình</button></div>
    <form v-if="home.showPlanForm" class="plan-form" @submit.prevent="home.createPlan"><div class="form-heading"><div><h2>Tạo lộ trình mới</h2><p>Chọn mục tiêu và thời gian học mỗi tuần.</p></div><button class="icon-action" type="button" aria-label="Đóng" @click="home.showPlanForm = false"><X :size="18" /></button></div><label class="form-field">Tên lộ trình<input v-model="home.planForm.title" required maxlength="200" placeholder="Ví dụ: Luyện thi IELTS" /></label><div class="form-row"><label class="form-field">Chứng chỉ<select v-model="home.selectedCertificateId"><option value="">Không chọn</option><option v-for="certificate in home.certificates" :key="certificate.certificateId" :value="String(certificate.certificateId)">{{ certificate.name }}</option></select></label><label class="form-field">Ngày dự kiến thi<input v-model="home.planForm.examDate" type="date" required /></label></div><div class="form-row"><label class="form-field">Điểm mục tiêu<input v-model="home.planForm.targetScore" type="number" min="0" step="0.5" placeholder="Ví dụ: 7.0" /></label><label class="form-field">Giờ học mỗi tuần<input v-model.number="home.planForm.hoursPerWeek" type="number" min="1" max="80" required /></label></div><div class="form-actions"><button class="secondary-button" type="button" @click="home.showPlanForm = false">Hủy</button><button class="primary-button" type="submit" :disabled="home.creatingPlan">{{ home.creatingPlan ? 'Đang tạo...' : 'Tạo kế hoạch' }}</button></div></form>
    <div v-if="home.plans.length" class="plan-list"><article v-for="plan in home.plans" :key="plan.planId" class="plan-row"><span class="plan-row-icon"><Compass :size="21" /></span><div class="plan-row-content"><div class="plan-row-title"><h2>{{ plan.title }}</h2><span :class="['plan-status', plan.status === 'ACTIVE' ? 'plan-active' : '']">{{ plan.status === 'ACTIVE' ? 'Đang học' : plan.status === 'COMPLETED' ? 'Hoàn thành' : 'Đã lưu trữ' }}</span></div><p>{{ home.certificates.find((certificate) => certificate.certificateId === plan.certificateId)?.name || 'Lộ trình học cá nhân' }} · {{ plan.hoursPerWeek }} giờ mỗi tuần · {{ home.formatDate(plan.examDate) }}</p><div class="plan-progress"><div><span :style="{ width: `${plan.taskCount ? Math.round(plan.completedCount / plan.taskCount * 100) : 0}%` }"></span></div><small>{{ plan.completedCount || 0 }} / {{ plan.taskCount || 0 }} nhiệm vụ</small></div><div class="roadmap-track" :aria-label="`Tiến độ ${plan.title}`"><div :class="{ reached: plan.completedCount > 0 }"><span>01</span><small>Bắt đầu</small></div><i :class="{ reached: plan.completedCount > 0 }"></i><div :class="{ reached: plan.completedCount > 0 && plan.completedCount < plan.taskCount, current: plan.status === 'ACTIVE' }"><span>02</span><small>Đang học</small></div><i :class="{ reached: plan.status === 'COMPLETED' }"></i><div :class="{ reached: plan.status === 'COMPLETED' }"><span>03</span><small>Hoàn thành</small></div></div></div><button class="icon-action" :title="`Xem thống kê ${plan.title}`" @click="home.showView('progress')"><ArrowRight :size="18" /></button></article></div>
    <div v-else-if="!home.loading && !home.showPlanForm" class="empty-page"><Compass :size="28" /><h2>Chưa có lộ trình</h2><p>Tạo kế hoạch theo ngày thi và số giờ học bạn có thể dành mỗi tuần.</p><button class="primary-button" @click="home.showPlanForm = true"><Plus :size="16" /> Tạo lộ trình đầu tiên</button></div>
  </section>
</template>
